package com.lqq.supportflow.action.infrastructure.persistence;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.baomidou.mybatisplus.core.conditions.update.UpdateWrapper; import com.lqq.supportflow.action.domain.*; import java.time.*; import org.springframework.stereotype.Component;
@Component public class MyBatisApprovalAdapter implements ApprovalPort { private final ApprovalMapper approvals; private final ApprovalDecisionMapper decisions; public MyBatisApprovalAdapter(ApprovalMapper approvals,ApprovalDecisionMapper decisions){this.approvals=approvals;this.decisions=decisions;} public Approval create(Long tenantId,Long customerId,String actionType,String actionSummary,Long requestedByMembershipId){Instant now=Instant.now();ApprovalEntity entity=new ApprovalEntity();entity.tenantId=tenantId;entity.customerId=customerId;entity.actionType=actionType;entity.actionSummary=actionSummary;entity.status=ApprovalStatus.PENDING.name();entity.requestedByMembershipId=requestedByMembershipId;entity.expiresAt=now.plus(Duration.ofMinutes(30));entity.version=0L;entity.createdAt=now;entity.updatedAt=now;approvals.insert(entity);return approval(entity);} public java.util.List<Approval> list(Long tenantId){expireOutstanding(tenantId);return approvals.selectList(new QueryWrapper<ApprovalEntity>().eq("tenant_id",tenantId).orderByDesc("created_at")).stream().map(this::approval).toList();} public Approval decide(Long tenantId,Long approvalId,Long membershipId,ApprovalStatus decision,String idempotencyKey){if(decision!=ApprovalStatus.APPROVED&&decision!=ApprovalStatus.REJECTED)throw new IllegalArgumentException("approval decision must be APPROVED or REJECTED");ApprovalDecisionEntity previous=decisions.selectOne(new QueryWrapper<ApprovalDecisionEntity>().eq("tenant_id",tenantId).eq("approval_id",approvalId).eq("idempotency_key",idempotencyKey));if(previous!=null)return approval(owned(tenantId,approvalId));ApprovalEntity source=owned(tenantId,approvalId);if(source.expiresAt.isBefore(Instant.now())){expire(tenantId,approvalId);return approval(owned(tenantId,approvalId));}if(!ApprovalStatus.PENDING.name().equals(source.status))throw new IllegalArgumentException("approval is not pending");int updated=approvals.update(new ApprovalEntity(),new UpdateWrapper<ApprovalEntity>().eq("id",approvalId).eq("tenant_id",tenantId).eq("version",source.version).eq("status",ApprovalStatus.PENDING.name()).set("status",decision.name()).set("decided_by_membership_id",membershipId).set("updated_at",Instant.now()).setSql("version = version + 1"));if(updated!=1)throw new IllegalArgumentException("approval changed concurrently");ApprovalDecisionEntity saved=new ApprovalDecisionEntity();saved.tenantId=tenantId;saved.approvalId=approvalId;saved.idempotencyKey=idempotencyKey;saved.decision=decision.name();saved.createdAt=Instant.now();decisions.insert(saved);return approval(owned(tenantId,approvalId));} private void expireOutstanding(Long tenantId){approvals.update(new ApprovalEntity(),new UpdateWrapper<ApprovalEntity>().eq("tenant_id",tenantId).eq("status",ApprovalStatus.PENDING.name()).lt("expires_at",Instant.now()).set("status",ApprovalStatus.EXPIRED.name()).set("updated_at",Instant.now()));} private void expire(Long tenantId,Long id){approvals.update(new ApprovalEntity(),new UpdateWrapper<ApprovalEntity>().eq("id",id).eq("tenant_id",tenantId).eq("status",ApprovalStatus.PENDING.name()).set("status",ApprovalStatus.EXPIRED.name()).set("updated_at",Instant.now()));} private ApprovalEntity owned(Long tenantId,Long id){ApprovalEntity entity=approvals.selectOne(new QueryWrapper<ApprovalEntity>().eq("id",id).eq("tenant_id",tenantId));if(entity==null)throw new IllegalArgumentException("approval does not belong to tenant");return entity;} private Approval approval(ApprovalEntity entity){return new Approval(entity.id,entity.actionType,entity.actionSummary,ApprovalStatus.valueOf(entity.status),entity.expiresAt);}}
